import{_ as s,o as a,c as i,a3 as n}from"./chunks/framework.B7pF4b99.js";const u=JSON.parse('{"title":"Spec 33：磁碟請求所有權與完成檢查","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-33-block-request-ownership.md","filePath":"SPEC-33-block-request-ownership.md","lastUpdated":1794274556000}'),l={name:"SPEC-33-block-request-ownership.md"};function t(p,e,r,o,c,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="spec-33-磁碟請求所有權與完成檢查" tabindex="-1">Spec 33：磁碟請求所有權與完成檢查 <a class="header-anchor" href="#spec-33-磁碟請求所有權與完成檢查" aria-label="Permalink to &quot;Spec 33：磁碟請求所有權與完成檢查&quot;">​</a></h1><blockquote><p>2026-11-10 合併註記：本文記錄本機分支的同步原型。現行程式已移植到遠端模組架構，磁碟使用 KernelGate、event、bounce buffer 與有界 reset/offline；IRQ 與 polling 共用 <code>poll_device</code>。FS／VM 使用遠端 KernelGate；本機 mutex 留在 <code>kernel/proc/kmutex.*</code> 與主機測試作為獨立原型，未接入 runtime。現況與驗證見<a href="./merge-2026-11-10.html">合併紀錄</a>。</p></blockquote><p>狀態：已實作，核心編譯與 QEMU 驗證待使用者執行。使用者同意先繼續實作，Spec 32 的 PLIC 測試仍保留為待辦，沒有視為通過。</p><h2 id="為什麼先處理這一層" tabindex="-1">為什麼先處理這一層 <a class="header-anchor" href="#為什麼先處理這一層" aria-label="Permalink to &quot;為什麼先處理這一層&quot;">​</a></h2><p>原本 block driver 用全域 <code>active</code> 配合巨集選擇磁碟。同步、單核心且 kernel 關中斷時能運作，但若在等待磁碟時切換行程，另一條路徑可能修改 <code>active</code>。請求恢復後不能再依賴這個全域選擇器。</p><p>本項將初始化、MMIO 位址設定、提交、完成與錯誤診斷全部改成明確傳入 <code>BlockDevice *</code>；WUFS 與 swap 各自保存 queue、請求 header、status、索引及狀態。每個裝置仍只允許一筆未釋放請求，固定使用 descriptor head 0。</p><p>這是等待／喚醒的前置機制。本項仍同步等待，沒有加入行程睡眠、核心搶占或多 hart 支援，也不能宣稱已解決 lost wakeup。上層 FS／VM 的操作、借用緩衝區與行程終止生命週期，仍須在開放排程前另行保護。</p><h2 id="請求狀態與演算法" tabindex="-1">請求狀態與演算法 <a class="header-anchor" href="#請求狀態與演算法" aria-label="Permalink to &quot;請求狀態與演算法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IDLE</span></span>
<span class="line"><span>  -&gt; 檢查 SIE=0、無舊請求、used index 已消耗</span></span>
<span class="line"><span>  -&gt; 填入 descriptor/header/status</span></span>
<span class="line"><span>  -&gt; INFLIGHT，先發布 descriptor，再發布 avail index，最後 notify</span></span>
<span class="line"><span>  -&gt; polling 或 IRQ callback 呼叫同一個 collect_completion</span></span>
<span class="line"><span>  -&gt; COMPLETE</span></span>
<span class="line"><span>  -&gt; 呼叫端取得結果，釋放借用緩衝區的所有權，回到 IDLE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>逾時、所有權衝突或損壞完成資料 -&gt; FAILED -&gt; 停止核心</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><code>collect_completion</code> 先讀取裝置發布的 used index，沒有變化便返回；有變化時執行 acquire fence，再檢查 used element 與 DMA status：</p><ul><li>使用 16-bit 差值處理 index 回繞。只有一筆 outstanding request，因此差值必須是 1。</li><li>descriptor head 必須是 0；完成長度不得超過本次可寫入範圍。</li><li>status 必須已從初始 <code>0xff</code> 改成支援的 OK／IOERR／UNSUPP。</li><li>此 modern VirtIO 驅動要求成功 read 完成 512-byte data 加 1-byte status；write 完成 1-byte status。錯誤回覆允許較短長度。</li><li>完成索引只由此函式推進；狀態改為 COMPLETE 後，重複 IRQ／輪詢不會再消耗一次。</li></ul><p>IRQ callback 先 ACK 裝置，再呼叫 collector；collector 不輸出、不睡眠、不切換行程，也不讓記憶體被重用。錯誤只標記 FAILED，由持有請求的同步呼叫端輸出診斷並停止核心。合法裝置 I/O 錯誤會完成請求並返回 <code>-1</code>；協定損壞則不返回，避免仍在 DMA 的記憶體被重用。</p><p>目前 kernel SIE 保持關閉，所以磁碟傳輸通常由輪詢先完成，IRQ 在回到 U-mode 後才處理。collector 兩個入口的互斥依賴單 hart、SIE=0；未來改變這個前提時必須重設同步策略。</p><h2 id="保留的測試提醒" tabindex="-1">保留的測試提醒 <a class="header-anchor" href="#保留的測試提醒" aria-label="Permalink to &quot;保留的測試提醒&quot;">​</a></h2><p>以下皆待使用者執行，沒有代跑核心編譯或 QEMU：</p><ul><li>[ ] Spec 32：正常磁碟順序的 IRQ 註冊、handled 增加、異常計數為零。</li><li>[ ] Spec 32：反轉磁碟順序仍能找到正確 WUFS／swap IRQ。</li><li>[ ] 本項：正常與反轉順序下，<code>ps</code> 顯示兩個磁碟 <code>state=idle</code>，各自 <code>submitted=completed</code>，<code>io_errors=0</code>、<code>protocol_errors=0</code>。</li><li>[ ] 本項：<code>ls /</code> 前後 WUFS submitted／completed 同步增加，讀取正常。</li><li>[ ] 回歸：<code>blank</code>、<code>damaged</code>、<code>tail</code> 磁碟保護案例與 GUI Terminal。</li><li>[ ] 邊界：used index 回繞、重複通知、錯誤 descriptor ID／長度／index／status、I/O 錯誤與逾時；目前沒有故障注入入口，正常開機不能代替這些驗證。</li></ul><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> valid</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> valid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reverse</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disks</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>兩次開機都在客體執行 <code>ps</code>、<code>ls /</code>、<code>ps</code>，依序觀察 IRQ 與 Block 計數，再按 Ctrl+A、放開後按 X 離開。測試工具的 PASS 仍只代表磁碟雜湊檢查，不代表 IRQ 或請求生命週期已驗證。</p><h2 id="下一步的限制" tabindex="-1">下一步的限制 <a class="header-anchor" href="#下一步的限制" aria-label="Permalink to &quot;下一步的限制&quot;">​</a></h2><p>真正讓磁碟等待切出 CPU 前，還需處理 FS／VM 上層互斥與借用緩衝區、swap 換頁期間的再入、等待者被 kill 時的 DMA 生命週期、原子檢查／等待／喚醒，以及無 Ready 行程時安全接收外部中斷的方式。不能直接在現有輪詢迴圈加入 <code>process_block_sync()</code>。</p><h2 id="參考" tabindex="-1">參考 <a class="header-anchor" href="#參考" aria-label="Permalink to &quot;參考&quot;">​</a></h2><ul><li><a href="./SPEC-32-plic-external-interrupts.html">Spec 32：PLIC 外部中斷派發骨架</a>。</li><li><a href="https://docs.oasis-open.org/virtio/virtio/v1.2/virtio-v1.2.html" target="_blank" rel="noreferrer">VirtIO 1.2：used ring 與 block device operation</a>。本驅動僅支援 modern MMIO，不沿用 legacy 忽略 used length 的行為。</li></ul>`,22)])])}const b=s(l,[["render",t]]);export{u as __pageData,b as default};
